using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class EnumFormatterCoverageAttributeTests
{
    private const string Source = """
        using MessagePack;

        public enum MyEnum { A, B }

        [MessagePackObject]
        public class MyObj
        {
            [Key(0)]
            public MyEnum Value { get; set; }
        }

        [GeneratedMessagePackResolver]
        partial class MyResolver { }
        """;

    [Fact]
    public async Task EnumFormatterHasExcludeFromCodeCoverage()
    {
        var classes = await GetGeneratedFormatterClassesAsync();
        var enumFormatters = classes.Where(c => c.BaseList is not null && c.BaseList.ToString().Contains("IMessagePackFormatter<") && c.BaseList.ToString().Contains("MyEnum")).ToList();
        Assert.NotEmpty(enumFormatters);
        foreach (var c in enumFormatters)
        {
            Assert.Contains(c.AttributeLists.SelectMany(al => al.Attributes), a => a.Name.ToString().Contains("ExcludeFromCodeCoverage"));
        }
    }

    private static async Task<List<ClassDeclarationSyntax>> GetGeneratedFormatterClassesAsync()
    {
        var parseOptions = new CSharpParseOptions(LanguageVersion.CSharp7_3);
        var framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var references = new List<MetadataReference>();
        references.AddRange(framework);
        references.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        var compilation = CSharpCompilation.Create(
            "ReceiptsEnumTest",
            new[] { CSharpSyntaxTree.ParseText(Source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGenerators(compilation);
        var result = driver.GetRunResult();
        var list = new List<ClassDeclarationSyntax>();
        foreach (var tree in result.GeneratedTrees)
        {
            var root = await tree.GetRootAsync();
            list.AddRange(root.DescendantNodes().OfType<ClassDeclarationSyntax>());
        }

        return list;
    }
}
